// 임대조건 한 줄 산술 단위 시험 — node .github/health/rent-arith.test.mjs (실패하면 종료 코드 1)
// 꼴은 역전파 14회차 ② 점검 식 한계 넷 + 두 벌 비고(…20822) — 실제 비고 문장을 줄여 썼다.
import { rentArith } from './rent-arith.mjs'
const one = (d, d1, note) => rentArith([['A', d, d1, note]])
const cases = [
  ['ⓐ 증액 한도 「-」(결과 = 계)', one(12236000, null, '계약금 611,800원·잔금 11,624,200원; 전환: 증액 한도 -(보증금 12,236,000원·월 63,210원)·감액 한도 10,000,000원(보증금 2,236,000원·월 92,370원)'), c => c.conv_n === 1 && c.conv_bad === 0],
  ['ⓐ 증액 한도 「0원」', one(4764000, null, '계약금 238,000원·잔금 4,526,000원; 전환: 증액 한도 0원(보증금 4,764,000원·월 54,440원)·감액 한도 3,000,000원(보증금 1,764,000원·월 63,190원)'), c => c.conv_bad === 0 && c.conv_n === 1],
  ['ⓑ 「원」 없는 한도 · 한도가 결과 뒤', one(15384000, null, '계약금 769,200원·잔금 14,614,800원; 전환 시 임대조건(+) 임대보증금 38,384,000원·월임대료 123,090원(전환가능 보증금 한도액 23,000,000); 최대전환 시 임대조건(-) 임대보증금 6,384,000원·월임대료 264,340원(전환가능 보증금 한도액 9,000,000)'), c => c.conv_n === 1 && c.conv_bad === 0],
  ['ⓒ 한도 칸 없이 결과만 — 판정 안 함', one(18551000, null, '계약금 500,000원·잔금 18,051,000원; 보증금 조정 가능조건 — ① 감액 임대보증금 4,551,000원·월임대료 154,980원 / ② 증액 임대보증금 28,551,000원·월임대료 64,150원'), c => c.conv_n === 0],
  ['ⓓ 「증액 한도 -·감액」 — 증액이 감액까지 안 읽힘', one(8545000, null, '계약금 427,250원·잔금 8,117,750원; 전환: 증액 한도 -·감액 한도 5,000,000원(보증금 3,545,000원·월 108,470원)'), c => c.conv_n === 1 && c.conv_bad === 0],
  ['「(+)L원 →」 꼴 · 원문 결손 잡음', one(8623000, null, '계약금 431,150원·잔금 8,191,850원; 전환시 — 증액 (+)16,000,000원 → 보증금 24,724,000원·월임대료 84,330원 / 감액 (-)4,000,000원 → 보증금 4,724,000원·월임대료 172,800원'), c => c.conv_bad === 1 && c.cand_conv.length === 1],
  ['두 벌 비고(가군·나군) — 거짓 양성 없음', one(3425000, 2452000, '가군: 임대보증금 계 2,452,000원(계약금 122,600원·잔금 2,329,400원)·월 48,810원 / 나군: 임대보증금 계 3,425,000원(계약금 171,250원·잔금 3,253,750원)·월 76,220원'), c => c.sum_bad === 0],
  ['합 어긋남 ∧ 전환 맞음 → 계약금·잔금 칸 후보', one(10000000, null, '계약금 500,000원·잔금 9,000,000원; 전환: 증액 한도 2,000,000원(보증금 12,000,000원·월 1원)'), c => c.sum_bad === 1 && c.cand_kj.length === 1],
  ['「/」로 갈린 짝', one(223200000, null, '계약금11,160,000원/잔금212,040,000원. 전환(+)104,000,000원→보증금327,200,000원'), c => c.rows === 1 && c.sum_bad === 0 && c.conv_n === 1 && c.conv_bad === 0],
]
let bad = 0
for (const [name, c, ok] of cases) {
  const pass = ok(c)
  if (!pass) bad++
  console.log(`${pass ? '✓' : '✗'} ${name} — ${JSON.stringify({ rows: c.rows, sum_bad: c.sum_bad, conv_n: c.conv_n, conv_bad: c.conv_bad })}`)
}
process.exit(bad ? 1 : 0)
